<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-primary transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 flex-1 truncate font-medium text-ui-ink-gray-900"
					>Penyesuaian Cuti</span
				>
				<span
					v-if="!loading"
					class="shrink-0 rounded-full bg-ui-surface-gray-100 px-2.5 py-0.5 text-xs font-medium text-ui-ink-gray-500"
					>{{ rows.length }}{{ hasMore ? '+' : '' }}</span
				>
			</div>

			<div class="relative mt-3">
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="pointer-events-none absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 text-ui-ink-gray-400"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<circle cx="11" cy="11" r="7" />
					<path d="m21 21-4.3-4.3" />
				</svg>
				<input
					v-model="search"
					type="search"
					inputmode="search"
					placeholder="Cari nama karyawan atau nomor…"
					class="w-full rounded-xl border border-ui-line-gray-200 bg-ui-surface-gray-50 py-2.5 pl-10 pr-3 text-base text-ui-ink-gray-900 placeholder:text-ui-ink-gray-400 focus:border-primary focus:bg-ui-surface focus:outline-none"
					@keyup.enter="reload"
				/>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="app-container-narrow flex-1 px-4 py-4 md:px-6">
			<pre v-if="error" class="whitespace-pre-wrap py-4 text-sm text-ui-ink-red-600">{{
				error
			}}</pre>

			<p v-else-if="loading && !rows.length" class="py-6 text-sm text-ui-ink-gray-500">
				Memuat…
			</p>

			<p v-else-if="!rows.length" class="py-10 text-center text-sm text-ui-ink-gray-400">
				Belum ada penyesuaian cuti.
			</p>

			<div v-else class="space-y-2.5">
				<button
					v-for="row in rows"
					:key="row.name"
					type="button"
					class="w-full rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 text-left shadow-sm transition hover:bg-ui-surface-gray-50 active:bg-ui-surface-gray-100"
					@click="buka(row.name)"
				>
					<div class="flex items-start gap-2">
						<span class="min-w-0 flex-1">
							<span
								class="block truncate text-base font-semibold text-ui-ink-gray-900"
								>{{ row.employee_name || row.employee }}</span
							>
							<span class="block truncate text-sm text-ui-ink-gray-500"
								>{{ row.leave_type }} · {{ row.name }}</span
							>
						</span>
						<span
							class="shrink-0 rounded-full px-2.5 py-0.5 text-xs font-medium"
							:class="badge(row.docstatus)"
							>{{ labelStatus(row.docstatus) }}</span
						>
					</div>

					<!-- Inti kartunya: dari rentang mana ke rentang mana. -->
					<div class="mt-2.5 flex flex-wrap items-center gap-1.5 text-sm">
						<span class="text-ui-ink-gray-400 line-through">{{
							rentang(row.from_date_semula, row.to_date_semula)
						}}</span>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4 shrink-0 text-ui-ink-gray-400"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M5 12h14" />
							<path d="m12 5 7 7-7 7" />
						</svg>
						<span class="font-medium text-ui-ink-gray-900">{{
							rentang(row.from_date, row.to_date)
						}}</span>
					</div>
				</button>

				<button
					v-if="hasMore"
					type="button"
					class="w-full rounded-xl border border-ui-line-gray-200 bg-ui-surface py-3 text-base font-medium text-primary transition hover:bg-ui-surface-blue-50 disabled:opacity-60"
					:disabled="loading"
					@click="muatLagi"
				>
					{{ loading ? 'Memuat…' : 'Muat lebih banyak' }}
				</button>
			</div>
		</div>
	</div>
</template>

<script setup>
/**
 * Daftar Penyesuaian Cuti (read-only).
 *
 * Dibuat HR di desk; di app hanya dibaca. Aksesnya murni mengikuti permission
 * doctype — query lewat `frappe.client.get_list` tanpa ignore_permissions,
 * jadi app tidak pernah menampilkan lebih banyak daripada desk.
 */
import { onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { rentang } from '../data/cutiStatus'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'

const PER_HALAMAN = 20
const router = useRouter()
const listPersistence = useListPersistence('PenyesuaianCuti')

const rows = ref([])
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')
const search = ref('')
search.value = listPersistence.readSession({ search: '' }).search
watch(search, (value) => {
	if (value) listPersistence.writeSession({ search: value })
	else listPersistence.clearSession()
})

function buka(name) {
	router.push({ name: 'PenyesuaianCutiDetail', params: { name } })
}

// docstatus, bukan field status: doctype ini tidak punya workflow — yang
// menentukan berlaku atau tidaknya hanya submit/cancel.
function labelStatus(d) {
	return { 0: 'Draft', 1: 'Diterapkan', 2: 'Dibatalkan' }[d] || '—'
}
function badge(d) {
	return (
		{
			0: 'bg-ui-surface-gray-200 text-ui-ink-gray-700',
			1: 'bg-ui-surface-green-100 text-ui-ink-green-700',
			2: 'bg-ui-surface-pink-100 text-ui-ink-pink-700',
		}[d] || 'bg-ui-surface-gray-200 text-ui-ink-gray-700'
	)
}

const list = createResource({
	url: 'frappe.client.get_list',
	auto: false,
	makeParams() {
		const p = {
			doctype: 'Penyesuaian Cuti',
			fields: JSON.stringify([
				'name',
				'employee',
				'employee_name',
				'leave_type',
				'from_date',
				'to_date',
				'from_date_semula',
				'to_date_semula',
				'docstatus',
			]),
			order_by: 'modified desc',
			limit_start: start.value,
			limit_page_length: PER_HALAMAN,
		}
		const q = search.value.trim()
		if (q) {
			p.or_filters = JSON.stringify([
				['employee_name', 'like', `%${q}%`],
				['name', 'like', `%${q}%`],
			])
		}
		return p
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
}
function muatLagi() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

onMounted(async () => {
	await refreshCsrfToken()
	reload()
})
</script>
